  const unscaled={T:G.sub(G.mul(b,ff,HH),j.U),RT:G.mul(q(2),G.sub(G.mul(b,j.U),j.V)),
    TT:G.add(j.V,G.mul(G.sub(G.one,G.mul(q(2),b)),j.U),G.mul(b,G.sub(b,G.one),ff,HH)),ZZ:G.neg(G.mul(q(2),f1,HH))};
