function gaussianTailMoment(n,M){
  if(n===0)return Q(3,M);if(n===1)return Q(3);
  return qadd(Q(3n*BigInt(M)**BigInt(n-1)),qmul(Q(3*(n-1)),gaussianTailMoment(n-2,M)));
}

