  const gp=ROOT+'.sourceGates',gates=array(d.sourceGates),gateTable=sourceTable('모멘트 복구와 다음 차수 소스 생성',['차수 전환','보정 전 차단','복사한 결과 차단','보정 후 허용','다음 소스 실제 생성','검사'],gates.map((g,i)=>{const p=gp+'['+i+']';return row(p,cell(g.name,p+'.name'),cell(g.beforeCorrectionRejected,p+'.beforeCorrectionRejected'),cell(g.copiedReportRejected,p+'.copiedReportRejected'),cell(g.afterCorrectionAccepted,p+'.afterCorrectionAccepted'),cell(g.actualNextSourceGenerated,p+'.actualNextSourceGenerated'),cell(g.pass,p+'.pass'));}),options);
  const gatePanel=tablePanel('actual-moment-source-gates','보정 완료 후에만 다음 차수로','실제 1차 복구 객체로 2차 source를 생성했습니다. 2차 복구는 3차 생성을 허용하는 상태까지 확인했으며, 이 예시에서 3차 source를 생성했다는 뜻은 아닙니다. 복구 전 객체와 결과를 복사한 객체가 통과하지 못하는지도 검사합니다.',gateTable,gp,'ACTUAL_PREVIOUS_ORDER_MOMENT_GATES',d);
  gatePanel.chart.rows=gates.map(g=>['n='+g.order+' → n='+g.nextOrder,'보정 전 차단 '+g.beforeCorrectionRejected+' · 보정 후 허용 '+g.afterCorrectionAccepted+' · 다음 소스 생성 '+g.actualNextSourceGenerated]);

  const pp=ROOT+'.innerProofs',pdeRows=array(d.innerProofs).flatMap((p,i)=>Object.entries(p.checks).map(([name,check])=>{const path=pp+'['+i+'].checks.'+name;return row(path,cell('n='+p.order+' · '+name),cell(check.pass,path+'.pass'),cell(check.numeratorMonomials,path+'.numeratorMonomials'),cell(check.denominatorMonomials,path+'.denominatorMonomials'),cell(check.expression,path+'.expression'));}));
  const pde=tablePanel('actual-moment-inner-pde','원래 내부 PDE · 두 차수의 항등식 12개','원래 여섯 성분 Picard 시스템의 수렴해를 압력·평균·각방향·축방향 식에 대입했습니다. 실제 forcing을 빠뜨리는 대조 검사가 실패하는지 함께 확인합니다. 유한 Picard 반복값을 해로 대체하지 않습니다.',sourceTable('원래 시스템에서 직접 확인한 내부 항등식',['차수·방정식','항등식 통과','분자 단항식 수','분모 단항식 수','원본 식 ID'],pdeRows,options),pp,'ACTUAL_TWO_ORDER_INNER_PDE_IDENTITIES',d);
