  const cp=ROOT+'.conservation',totals=array(d.conservation.totals),totalRows=totals.flatMap((t,i)=>[['theta','θ'],['z','z']].map(([component,label])=>{const p=cp+'.totals['+i+']';return row(p,cell('n='+t.order+' · '+label),cell(t[component],p+'.'+component),cell(t[component+'Reduced'],p+'.'+component+'Reduced'));}));
  const conservation=tablePanel('actual-moment-conservation','네 응력 적분 · 실제 모멘트와 열 보상','보정된 모멘트와 η 도함수, 원래 leading flux 및 열을 뺀 angular moment를 연결해 네 보존형 total을 정확히 0으로 환원합니다. 1차 각응력에 필요한 실제 heat 함수와 도함수도 유지합니다.',sourceTable('각 차수의 두 보존형 total',['차수·성분','환원 전 원본 식 ID','정확한 0 노드 ID'],totalRows,options),cp,'ACTUAL_FOUR_CONSERVATIVE_STRESS_TOTALS',d);
